import _hyalos

_FIRST_DATA = 3
_LABELS = ("bug", "feature", "security", "other")
_NUMBER_MAX = 4294967295


def _bytes(value):
    if isinstance(value, str):
        return value.encode()
    return bytes(value)


def _number(text):
    if not text:
        return None
    n = 0
    for c in text:
        if c < 48 or c > 57:
            return None
        n = n * 10 + (c - 48)
    if n > _NUMBER_MAX:
        return None
    return n


class _Issue:
    def __init__(self, number, title):
        self.number = number
        self.title = title


def _issue(record):
    if not record:
        return _Issue(None, None)
    tab = record.find(b"\t")
    if tab < 0:
        return _Issue(None, None)
    return _Issue(_number(record[:tab]), record[tab + 1:])


class _Ask:
    def classify(self, text):
        label = _hyalos.infer(0, _bytes(text))
        if 0 <= label < len(_LABELS):
            return _LABELS[label]
        return "other"


class _Task:
    def read_inputs(self):
        issues = []
        index = _FIRST_DATA
        while True:
            record = _hyalos.read(index)
            if record is None:
                return issues
            issues.append(_issue(record))
            index += 1

    def finish(self, text):
        _hyalos.finish(_bytes(text))


task = _Task()
task.ask = _Ask()
